export function semanticFeedbackLoop(decisionOutcome, historicalData) {
  const adjustedThresholds = { ...historicalData.thresholds };

  if (decisionOutcome.success) {
    adjustedThresholds[decisionOutcome.type] += 0.05;
  } else {
    adjustedThresholds[decisionOutcome.type] -= 0.05;
  }

  return adjustedThresholds;
}